-- 10: attach the old Carrd portfolio's trailers and store links to project titles (value.projects[].details).
-- Paste the whole file into the Supabase SQL editor and Run. Safe to re-run: details already set in the CMS win.
update public.content c
set value = jsonb_set(c.value, '{projects}', (
      select jsonb_agg(
        case when m.media is null then p
             else jsonb_set(p, '{details}', m.media || coalesce(p->'details', '{}'::jsonb)) end
        order by p_i)
      from jsonb_array_elements(c.value->'projects') with ordinality as x(p, p_i)
      left join (values
        ('anime', '{"Welcome to Demon School! Iruma-kun S4 (translator Ep. 1–14, editor from Ep. 15)":{"video":"https://www.youtube.com/watch?v=cN1bzy5Olik"},"Shiboyugi: Playing Death Games to Put Food on the Table, incl. the movie \"44: Cloudy Beach\"":{"video":"https://www.youtube.com/watch?v=FwFg-yLkOy4","link":"https://www.youtube.com/watch?v=Z6Px75XDEzw"},"Agents of the Four Seasons: Dance of Spring (except opening/ending songs)":{"video":"https://www.youtube.com/watch?v=mpNqO3FhZqk"},"Wind Breaker S2 (except opening/ending songs)":{"video":"https://www.youtube.com/watch?v=GGdale6NIYo"},"A Sign of Affection (except opening song)":{"link":"https://www.youtube.com/playlist?list=PLwLSw1_eDZl14kD6iz4eILaU9kceG6UZL"},"A Nobody''s Way Up to an Exploration Hero (except trailers)":{"video":"https://www.youtube.com/watch?v=z9jF5CzkWiU"},"Isekai Quartet 3":{"video":"https://www.youtube.com/watch?v=llg4gTH16yc"},"The Fated Magical Princess":{"video":"https://www.youtube.com/watch?v=JV4Og5Dyhf0"},"My Status as an Assassin Obviously Exceeds the Hero''s":{"video":"https://www.youtube.com/watch?v=h91kJbpqSIk"},"Apocalypse Bringer Mynoghra":{"video":"https://www.youtube.com/watch?v=yrskd694hoI"},"Demon Lord 2099":{"video":"https://www.youtube.com/watch?v=LlTBRwobaLw"},"I Parry Everything":{"video":"https://www.youtube.com/watch?v=AskspVq0HQo"},"Jellyfish Can''t Swim in the Night":{"video":"https://www.youtube.com/watch?v=_AqC7_OPDpo"},"Tenchi Muyo! Ryo-Ohki 4th Season":{"video":"https://www.youtube.com/watch?v=kO1qaZ2kslM"},"Tenchi Muyo! Ryo-Ohki 5th Season (co-translator & editor)":{"video":"https://www.youtube.com/watch?v=uHTSh72Y0bs"}}'::jsonb),
        ('quality', '{"Lord of Mysteries S1 (Chinese → English)":{"video":"https://www.youtube.com/watch?v=qm-qmzKTUX0"},"Seven Deadly Sins S1":{"link":"https://www.youtube.com/playlist?list=PLwLSw1_eDZl3572W1HJjIkZyW-0GGVUVq"},"Kaguya-sama: The Stairway to Adulthood":{"video":"https://www.youtube.com/watch?v=Mu8R6XtDsdU"},"SPY×FAMILY S1 & S2 (Tagalog QC)":{"video":"https://www.youtube.com/watch?v=dGBev16CUFo"},"Kaiju Girl Caramelise (Ep. 8)":{"video":"https://www.youtube.com/watch?v=moEEN9lxDOE"},"Mushoku Tensei S3 (Ep. 8)":{"video":"https://www.youtube.com/watch?v=b9MxZ7rjaGs"},"The World''s Strongest Rearguard (Ep. 7)":{"video":"https://www.youtube.com/watch?v=GJTHYFDMU9E"},"Easygoing Territory Defense (Ep. 8)":{"video":"https://www.youtube.com/watch?v=-KDO0piOCEs"},"Scum of the Brave (Ep. 8)":{"video":"https://www.youtube.com/watch?v=JuGnXFKhzqM"},"Isekai Office Worker (Ep. 9)":{"video":"https://www.youtube.com/watch?v=H46WXPKGwuQ"},"One Punch Man 3 (Ep. 12)":{"video":"https://www.youtube.com/watch?v=klax4pvvVBM"},"SPY×FAMILY S3 (Ep. 50)":{"video":"https://www.youtube.com/watch?v=h_tL16PZ0IE"},"Shangri-La Frontier (Ep. 47)":{"video":"https://www.youtube.com/watch?v=WRdgjUG793c"},"Beheneko (Ep. 11)":{"video":"https://www.youtube.com/watch?v=lt4dK8iTFOg"},"Even Given the Worthless \"Appraiser\" Class (Ep. 9)":{"video":"https://www.youtube.com/watch?v=zJ8djL-lYSg"}}'::jsonb),
        ('promo', '{"I Left My A-Rank Party… (Muse Asia)":{"video":"https://www.youtube.com/watch?v=JkBPYS8e2fQ"},"The Boyfriend (Netflix, via ZOO Digital)":{"video":"https://www.youtube.com/watch?v=S59NnFgnQRc"}}'::jsonb),
        ('games', '{"Return to Zeroes — Translator, Localization Lead, PM, PR Strategy & Overseas Liaison, QA (TABINOMICHI)":{"link":"https://store.steampowered.com/app/3162900/"},"Kugayama Shiori''s Death Diary — Translator, Localization Lead, PM, PR Strategy & Overseas Liaison, Debugging (Laplacian)":{"link":"https://store.steampowered.com/app/4141950/"},"Harmonic Reflections (retranslation) — Translator, Localization Lead, PM, PR Strategy & Overseas Liaison (Laplacian)":{"link":"https://store.steampowered.com/app/3782920/"},"Summer Snow. — Translator, Localization Lead, PM, PR Strategy & Overseas Liaison (Cynical Honey)":{"link":"https://store.steampowered.com/app/4933880/"},"Cyanotype Daydream, Switch version — Translator, new Switch content (Laplacian)":{"link":"https://laplacian.jp/yonagi/en/special"},"Inazuma Eleven: Victory Road — Translator, NPC dialogue (Level-5)":{"link":"https://www.inazuma.jp/victory-road/en/"},"Kenzen 3 (18+) — Translator, credited as \"Jchah\" (MangaGamer)":{"link":"https://mangagamer.org/kenzen3/"}}'::jsonb)
      ) as m(slug, media) on m.slug = p->>'slug'
    )),
    updated_at = now()
where c.key = 'site';
